    if(j===1){var price=pick([20,30,50,80],k%4),varc=pick([8,12,20,35],j%4),fixed=pick([240,360,500,800],(k+1)%4),units=fixed/(price-varc);return n("", "Цена единицы "+price+", переменная себестоимость "+varc+", фиксированные затраты "+fixed+". Сколько единиц нужно для break-even?",units,"ед.",["Маржа единицы: "+price+" − "+varc+" = "+(price-varc)+".","Break-even = "+fixed+" / "+(price-varc)+" = "+f(units,1)+" единиц."],"Делить нужно на маржу единицы, не на цену.",0.3);}
