    if(j===0){ans=start+step*5;return n("", "Продолжите ряд: "+start+", "+(start+step)+", "+(start+2*step)+", "+(start+3*step)+", ?",ans,"",["Разность постоянна: +"+step+".","Следующее число: "+ans+"."],"Проверь сначала разности соседних членов.",0.1);}
    if(j===1){var ratio=pick([2,3,4],k%3);ans=start*Math.pow(ratio,4);return n("", "Продолжите ряд: "+start+", "+start*ratio+", "+start*ratio*ratio+", "+start*ratio*ratio*ratio+", ?",ans,"",["Каждый раз умножаем на "+ratio+".","Следующий член = "+ans+"."],"Ищи отношение, если разности быстро растут.",0.1);}
    if(j===2){var x=pick([3,4,5,6],k%4);ans=(x+4)*(x+4);return n("", "Продолжите ряд квадратов: "+x*x+", "+(x+1)*(x+1)+", "+(x+2)*(x+2)+", ?",ans,"",["Это квадраты последовательных чисел.",""+(x+3)+"² = "+ans+"."],"Проверь корни членов ряда.",0.1);}
    if(j===3){var a=pick([64,81,100,121],k%4);ans=a/8;return n("", "Продолжите ряд деления: "+a+", "+a/2+", "+a/4+", ?",ans,"",["Каждый шаг делит на 2.",a/4+" / 2 = "+ans+"."],"Не ищи сложную формулу, пока не проверил постоянный делитель.",0.1);}
    if(j===4){var a1=start,b1=start+step;ans=2*a1+3*b1;return n("", "Продолжите ряд Фибоначчи: "+a1+", "+b1+", "+(a1+b1)+", "+(a1+2*b1)+", ?",ans,"",["Каждый член — сумма двух предыдущих.","Следующий = "+ans+"."],"Сложи два последних числа, а не первые.",0.1);}
    if(j===5){var cube=pick([2,3,4,5],k%4);ans=(cube+1)*(cube+1)*(cube+1);return n("", "Продолжите ряд кубов: "+cube*cube*cube+", "+(cube+1)*(cube+1)*(cube+1)+", "+(cube+2)*(cube+2)*(cube+2)+", ?",ans,"",["Члены — кубы последовательных чисел.",""+(cube+3)+"³ = "+ans+"."],"Не путай кубы с квадратами.",0.1);}
    if(j===6){var second=start*2+1,third=start*4+3,next=third*2+1;return n("", "Продолжите ряд: "+start+", "+second+", "+third+", ?",next,"",["Правило: умножить на 2 и прибавить 1.","Следующий = "+next+"."],"Проверь правило на всех переходах.",0.1);}
    if(j===7){var q=pick([3,4,5],k%3);ans=q*3;return n("", "Продолжите ряд: "+q*9+", "+q*6+", "+q*3+", ?",ans- q*3,"",["Каждый раз вычитаем "+(q*3)+".","Следующий = "+(q*3-q*3)+"."],"Смотри на постоянную разность.",0.1);}
    if(j===8){var n1=pick([2,3,4],k%3);ans=n1*n1+(n1+1)*(n1+1);return n("", "Продолжите ряд: "+n1*n1+", "+(n1+1)*(n1+1)+", "+(n1+2)*(n1+2)+", ?",(n1+3)*(n1+3),"",["Квадраты растущих чисел.","Следующий квадрат = "+((n1+3)*(n1+3))+"."],"Сначала проверь простую последовательность квадратов.",0.1);}
    ans=start+step*5;return n("", "Продолжите арифметический ряд с шагом "+step+": "+start+", "+(start+step)+", "+(start+2*step)+", "+(start+3*step)+", "+(start+4*step)+", ?",ans,"",["Ещё один шаг +"+step+" даёт "+ans+"."],"Не меняй правило посреди ряда.",0.1);
