    for(var mask=0;mask<8;mask++){
      var state=[!!(mask&4),!!(mask&2),!!(mask&1)];if(state.every(function(x,j){return x===c.answer[j];}))continue;
      for(var si=0;si<3;si++)if(preds[si].fn(state)!==state[si]){sol.push("Вариант «"+options[mask]+"» отпадает: фраза "+names[si]+" "+(preds[si].fn(state)?"истинна":"ложна")+", но "+names[si]+" здесь "+(state[si]?"правдивец":"лжец")+".");break;}
    }
    var q=mc("","Все трое всегда либо говорят правду, либо всегда лгут. "+text+" Какое распределение типов согласуется со всеми фразами?",options,correct,sol,"Не оценивай фразу по звучанию: её истинность зависит от выбранных типов, а тип говорящего обязан с ней совпасть.");
    q.skill="l3_truth_table";q.skillTitle="Проверять правдивцев и лжецов перебором вариантов";q.level=1+Math.min(4,Math.floor(i*5/81));return q;
