    if(family===0){var a=1+k%3,b=a+1+k%4,c=b+2+k%5,d=c+3+k%7,p1=a+3*b+d,p2=2*a+b+c+d,ans=Math.min(p1,p2);q=n("","Четверым нужно перейти мост за "+a+", "+b+", "+c+" и "+d+" минут. Фонарь один, идут не более двух, скорость пары равна скорости медленного. Минимальное время?",ans,"минут",["Сравни две стратегии для двух самых медленных.","Быстрые вместе: "+a+" + "+b+" + "+d+" + "+b+" + "+b+" = "+p1+" минут.","Быстрый сопровождает медленных по одному: "+d+" + "+a+" + "+c+" + "+a+" + "+b+" = "+p2+" минут.","Минимум: min("+p1+", "+p2+") = "+ans+" минут."],"Считай и переходы вперёд, и возвраты фонаря; не выбирай по первому ходу.",0.1);q.skill="c1_bridge";}
    else if(family===1){var floors=[10,15,20,28,36,45,55,66,78,91][k],throws=0;while(throws*(throws+1)/2<floors)throws++;var drops=[],floor=0,step=throws;while(floor<floors){floor=Math.min(floors,floor+step);drops.push(floor);step--;}q=n("","Есть два одинаковых предмета и "+floors+" этажей. Выше границы предмет разбивается, ниже — нет. Какое минимальное число бросков гарантирует найти границу в худшем случае?",throws,"бросков",["С первым предметом поднимайся на уменьшающиеся шаги: "+throws+", "+(throws-1)+", "+(throws-2)+"…", "Первые этажи проверки: "+drops.join(", ")+".","Если первый предмет разбился, вторым проверяй промежуток снизу по одному этажу.","Сумма "+throws+" + "+(throws-1)+" + … + 1 = "+(throws*(throws+1)/2)+" покрывает "+floors+" этажей."],"Постоянный шаг не выравнивает худший случай: после каждого броска остаётся меньше проверок.",0.1);q.skill="c1_egg";}
    else if(family===2){var bottles=[5,7,9,13,17,25,33,50,65,100][k],sensors=0;while(Math.pow(2,sensors)<bottles)sensors++;q=n("","Одна бутылка из "+bottles+" отравлена. Датчик выдаёт один бит: сработал или нет. Какое минимальное число датчиков позволяет определить бутылку за один раунд?",sensors,"датчиков",["Один датчик делит кандидатов на две группы по сигналу.","С "+sensors+" датчиками получается 2^"+sensors+" = "+Math.pow(2,sensors)+" разных наборов сигналов.","Это покрывает "+bottles+" бутылок; "+(sensors-1)+" датчиков дали бы только "+Math.pow(2,sensors-1)+" комбинаций."],"Число датчиков связано с двоичными комбинациями, а не с числом отдельных бутылок.",0.1);q.skill="c1_binary";}
    else{var doors=20+17*k,squares=[];for(var z=1;z*z<=doors;z++)squares.push(z*z);var ans=squares.length;q=n("","Есть "+doors+" дверей. На проходе №n меняют состояние дверей с номерами, кратными n. Сколько останется открытыми после всех проходов?",ans,"дверей",["Дверь меняет состояние один раз за каждый свой делитель.","Делители обычно идут парами: например, 12 = 1×12 = 2×6 = 3×4, поэтому число переключений чётное и дверь закрыта.","У полного квадрата один делитель в паре совпадает, поэтому делителей нечётное число и дверь остаётся открытой.","Квадраты до "+doors+": "+squares.join(", ")+". Их "+ans+"."],"Ищи номера с нечётным числом делителей: это полные квадраты.",0.1);q.skill="c1_doors";}
