  function addOpenGrid(id,contexts,groups){
    var items=[],complexity=["Пока затронута одна функция и срок не сдвигается.","Под угрозой ближайшая внутренняя веха.","Нужно согласовать две функции, которые по-разному понимают цель.","Часть данных спорная, а один шаг трудно отменить.","Есть внешний дедлайн, конфликт приоритетов и непроверенное допущение."];
    groups.forEach(function(g){contexts.forEach(function(context,i){
      var level=i%5+1;
      items.push([g.prompt(context,complexity[level-1]),g.model,g.trap,g.skill,level,g.decode,g.title]);
    });});
    addOpen(id,items);
  }

