    if(j===1)return mc("", "Проект A даёт "+a+"k эффекта с вероятностью 70%, стоит "+b+"k. Что сравнивать первым?",["Ожидаемый чистый эффект и риск","Только максимальный эффект","Только стоимость","Только срок"],0,["0,7×эффект − стоимость, затем риск и обязательность."],"Одна колонка таблицы не даёт решения.");
