    if(j===4)return n("", "Проект стоит "+b+"k и имеет вероятность успеха "+pick([0.5,0.7,0.8],k%3)*100+"%. Эффект при успехе "+a+"k. EV?",a*pick([0.5,0.7,0.8],k%3)-b,"k",["Вероятность × эффект − стоимость."],"Не путай эффект и ожидаемый эффект.",0.5);
    if(j===5){var ownerCases=["У проекта высокий эффект, но не назначен владелец.","У критической зависимости нет ответственного за закрытие.","После запуска результат некому передать в операционную поддержку.","У ключевого риска нет владельца и срока проверки.","Целевой бизнес-эффект рассчитан, но никто не отвечает за его подтверждение.","Поставщик нарушает SLA, а внутренний владелец эскалации не определён.","Решение нужно от функции, но accountable owner со стороны проекта не назначен.","На межфункциональный результат назначили трёх со-руководителей без одного ответственного.","Рабочий поток отстаёт, но никто не отвечает за восстановительный план."];return mc("", "В таблице отмечено: "+pick(ownerCases,k)+" Что сделать прежде, чем считать проект исполнимым?",["Продолжить запуск: эффект важнее управления","Назначить одного ответственного с полномочиями, сроком и ожидаемым результатом","Добавить общий статус без владельца","Исключить проект, не проверяя последствия"],1,["Сначала назначь одного accountable owner и проверь, что у него есть полномочия, срок и ясный результат."],"Высокий эффект без конкретного владельца не превращается в исполнимый проект.");}
    if(j===6){var r1=50+5*k,r2=60+4*k,r3=50+5*(k%5),combined=r1/100*r2/100*r3/100*100;return n("", "Воронка: на первом этапе проходит "+r1+"%, на втором "+r2+"%, на третьем "+r3+"%. Какова сквозная конверсия?",combined,"%",["Переведи каждый процент в долю: "+f(r1/100,2)+" × "+f(r2/100,2)+" × "+f(r3/100,2)+".","Перемножь доли этапов: "+pct(combined)+"."],"Конверсии этапов не усредняются: каждый следующий процент применяется к оставшимся людям или заявкам.",0.2);}
