      a=20+3*round;b=25+2*round;ans=a*b/100;return tag(n("","События A и B независимы. Вероятность A равна "+a+"%, вероятность B — "+b+"%. Какова вероятность, что произойдут оба?",ans,"%",["Независимость означает, что для совместного события вероятности перемножаются.",f(a/100,2)+"×"+f(b/100,2)+" = "+pct(ans)+"."],"Для независимого «и» умножай вероятности; для «или» обычно складывают с поправкой на пересечение.",0.1),"p1_and");
