      if(family2===1){prob=(30+2*round2)/100;tries=4+round2;ans=(1-Math.pow(1-prob,tries))*100;return tag(n("","Одна попытка проходит проверку с вероятностью "+pct(prob*100)+". Проводят "+tries+" независимых попыток. Какова вероятность хотя бы одного успеха?",ans,"%",["Противоположное событие — все попытки неуспешны.","Неуспех одной попытки: 1−"+f(prob,2)+" = "+f(1-prob,2)+".","Все неуспехи: "+f(1-prob,2)+"^"+tries+" = "+pct(Math.pow(1-prob,tries)*100)+".","Вычитаем из 100%: ответ "+pct(ans)+"."],"Хотя бы один успех — не то же самое, что число попыток, умноженное на шанс.",0.1),"p2_at_least_one");}
