      base3=2+round3;sens3=75+round3;false3=1+(round3%8);ans=base3*sens3/(base3*sens3+(100-base3)*false3)*100;return tag(n("","У службы безопасности инцидент есть у "+base3+"% проверок. Сигнал срабатывает при инциденте в "+sens3+"% случаев и ложно срабатывает в "+false3+"% проверок без инцидента. Сигнал появился. Какова вероятность настоящего инцидента?",ans,"%",["Представь одинаковое число проверок с инцидентом и без него.","Настоящие сигналы пропорциональны "+base3+"×"+sens3+" = "+(base3*sens3)+".","Ложные сигналы пропорциональны "+(100-base3)+"×"+false3+" = "+((100-base3)*false3)+".","Доля настоящих сигналов среди всех сработавших = "+pct(ans)+"."],"Редкий инцидент может давать много ложных тревог, даже если сигнализация довольно чувствительна.",0.1),"p3_false_positive");
