      if(familyL1===0){a=1+roundL1;b=3+(roundL1%8);seqL1=[a,a+b,a+2*b+2,a+3*b+6];ans=a+4*b+12;return tag(n("","Продолжи ряд: "+seqL1.join(", ")+", ?",ans,"",["Разности: +"+b+", +"+(b+2)+", +"+(b+4)+".","Разность сама каждый раз растёт на 2, значит следующая равна "+(b+6)+".",seqL1[3]+" + "+(b+6)+" = "+ans+"."],"Проверь, как меняются промежутки между числами, а не только последнее число.",0.1),"l1_second_difference");}
