      a=1+roundL1;b=2+(roundL1%9);c=2+(roundL1%4);seqL1=[a,a+b,(a+b)*c,(a+b)*c+b,((a+b)*c+b)*c];ans=seqL1[4]+b;return tag(n("","Продолжи ряд: "+seqL1.join(", ")+", ?",ans,"",["Здесь чередуются две операции: прибавить "+b+", затем умножить на "+c+".",a+" + "+b+" = "+seqL1[1]+"; затем ×"+c+" = "+seqL1[2]+".","После последнего умножения очередь снова за сложением: "+seqL1[4]+" + "+b+" = "+ans+"."],"Проверь повторяющуюся пару операций, а не ищи одно действие для всего ряда.",0.1),"l1_alternating_operations");
