      var pAltPM3=10+(roundPM3%61),impactAltPM3=80+25*roundPM3;evBpm3=pAltPM3/100*impactAltPM3;ans=Math.abs(evApm3-evBpm3);return tag(n("","Сравни риск A: вероятность "+a+"%, ущерб "+b+"k; и риск B: вероятность "+pAltPM3+"%, ущерб "+impactAltPM3+"k. На сколько отличаются их ожидаемые потери?",ans,"k",["Для A: "+a+"%×"+b+" = "+f(evApm3,1)+"k.","Для B: "+pAltPM3+"%×"+impactAltPM3+" = "+f(evBpm3,1)+"k.","Разница по модулю: |"+f(evApm3,1)+" − "+f(evBpm3,1)+"| = "+f(ans,1)+"k."],"Не выбирай риск по одной вероятности или одному ущербу: сначала умножь вероятность на влияние.",0.1),"pm3_risk_measure");
