  BANK.modules.forEach(function(m){m.types.forEach(function(t){
    var seen=new Set(),seed=0;
    t.qs.forEach(function(q,i){
      var prompt=q.t.trim();
      if(seen.has(prompt)){
        var replacement=null;
        for(var attempts=0;attempts<1000&&!replacement;attempts++){
          var candidate=variedReplacement(t.id,seed++);
          if(candidate&&!seen.has(candidate.t.trim()))replacement=candidate;
        }
        if(!replacement)throw new Error("No unique replacement available for "+t.id+" / "+q.id);
        replacement.id=q.id.replace(/_v\d+$/,"")+"_v4";
        replacement.level=q.level||1;
        t.qs[i]=q=replacement;
        prompt=q.t.trim();
      }
      seen.add(prompt);
    });
  });});

